// Fits props generated by scripts/props/generate.py (scripts/props/out/<id>/{model.glb,image.png}) to the island and
// writes them as catalog furniture: public/gltf/decor/<id>.glb and its drawer picture public/gltf/decor/thumbs/<id>.webp,
// which a server migration lists (scripts/props-catalog.mjs writes it). Studio furniture is placed at scale 1, so the
// GLB is the placed size, in metres: the manifest's `fit` (height or width), or else the placed box of the package model
// the item was once made to replace (its file's box times the engine catalog's `defaultScale`). Every model gets a
// bottom-centre pivot, matte non-metal materials and WebP maps; the picture is the generated image, trimmed and centred.
// Usage: node scripts/props-normalize.mjs [ids...]    (default: every manifest item that has a generated model)
// PROPS_SOURCE=<dir> reads generated models from another out/ directory; PROPS_OUTPUT=<dir> writes somewhere other than
// public/gltf.
// --replace writes public/gltf/<file> instead, fitted to the package model's own box and pivot, which the app then serves
// in place of the package's model (vite/gaesupAssets.ts: a public/ file of the same path wins), changing the village
// itself. That was tried once and reverted (bbdbe31); it writes no picture.
import { existsSync, mkdirSync, readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { getBounds, NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import { dedup, prune, textureCompress } from '@gltf-transform/functions';
import { MeshoptDecoder, MeshoptEncoder } from 'meshoptimizer';
import sharp from 'sharp';

const frontend = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const props = resolve(frontend, '../scripts/props');
const packageGltf = resolve(dirname(fileURLToPath(import.meta.resolve('gaesup-world'))), '../public/gltf');
const manifest = JSON.parse(readFileSync(join(props, 'manifest.json'), 'utf8'));
const args = process.argv.slice(2);
const replace = args.includes('--replace');
const wanted = new Set(args.filter((arg) => !arg.startsWith('--')));
const sourceDir = process.env['PROPS_SOURCE'] ?? join(props, 'out');
const outputDir = process.env['PROPS_OUTPUT'] ?? join(frontend, 'public/gltf');
/** Props are a few metres from a camera ~15 m away: 512 px colour maps are plenty. */
const MAPS = { resize: [512, 512], quality: 86 };
/** The island's props are matte; generated PBR sets come with metal and gloss that read as black or white patches. */
const ROUGHNESS = 0.9;
/** How far past the replaced model's footprint a plant or rock may reach, as a factor. */
const FOOTPRINT_SLACK = 1.25;
/** Drawer pictures: the generated image trimmed of its white margin, fitted in `PICTURE.fit` px, centred in `PICTURE.size`. */
const PICTURE = { size: 160, fit: 144, webp: { quality: 82, effort: 6 } };

await Promise.all([MeshoptDecoder.ready, MeshoptEncoder.ready]);
const io = new NodeIO()
  .registerExtensions(ALL_EXTENSIONS)
  .registerDependencies({ 'meshopt.decoder': MeshoptDecoder, 'meshopt.encoder': MeshoptEncoder });

function boxOf(document) {
  const { min, max } = getBounds(document.getRoot().getDefaultScene() ?? document.getRoot().listScenes()[0]);
  return { min, max, size: max.map((value, axis) => value - min[axis]) };
}

let engineCatalog;
/** The scale the engine places the package model at (its catalog's `defaultScale`): what makes its box the island size. */
async function placedScale(item) {
  engineCatalog ??= (await import('gaesup-world/building')).DEFAULT_BUILDING_OBJECT_CATALOG;
  const entry = engineCatalog.find((object) => object.id === item.id || object.modelUrl === `gltf/${item.file}`);
  if (!entry) throw new Error(`${item.id}: no engine catalog entry for ${item.file}; give it a manifest \`fit\``);
  return entry.defaultScale ?? 1;
}

/** The box `item` takes on the island, or null when the manifest's `fit` sizes it. */
async function targetOf(item) {
  if (item.fit) return null;
  const box = boxOf(await io.read(join(packageGltf, item.file)));
  if (replace) return box;
  const scale = await placedScale(item);
  const times = (values) => values.map((value) => value * scale);
  return { min: times(box.min), max: times(box.max), size: times(box.size) };
}

/** The drawer picture, made the way the first 37 decor pictures were: trimmed, fitted, centred on a clear square. */
async function writePicture(image, output) {
  const fitted = await sharp(image).trim().resize(PICTURE.fit, PICTURE.fit, { fit: 'inside' }).toBuffer({ resolveWithObject: true });
  const { width, height } = fitted.info;
  const left = Math.floor((PICTURE.size - width) / 2);
  const top = Math.floor((PICTURE.size - height) / 2);
  mkdirSync(dirname(output), { recursive: true });
  await sharp(fitted.data)
    .ensureAlpha()
    .extend({ left, top, right: PICTURE.size - width - left, bottom: PICTURE.size - height - top, background: { r: 0, g: 0, b: 0, alpha: 0 } })
    .webp(PICTURE.webp)
    .toFile(output);
}

async function fit(item) {
  const source = join(sourceDir, item.id, 'model.glb');
  if (!existsSync(source)) return `${item.id}: no generated model`;
  const image = join(sourceDir, item.id, 'image.png');
  if (!replace && !existsSync(image)) return `${item.id}: no generated image for the drawer picture`;
  // New decor stands on the origin at its `fit` size; the others take the package model's box.
  const target = await targetOf(item);
  const document = await io.read(source);
  const scene = document.getRoot().getDefaultScene() ?? document.getRoot().listScenes()[0];
  const wrapper = document.createNode(`${item.id}-fit`);
  for (const child of scene.listChildren()) {
    scene.removeChild(child);
    wrapper.addChild(child);
  }
  scene.addChild(wrapper);
  // Face the way the package model faced (set `yaw` in the manifest when a generated model looks the other way),
  // and lay a long piece of furniture along the same axis; plants and rocks have no front.
  let yaw = ((item.yaw ?? 0) * Math.PI) / 180;
  const quarter = (angle) => [0, Math.sin(angle / 2), 0, Math.cos(angle / 2)];
  wrapper.setRotation(quarter(yaw));
  let turned = boxOf(document);
  const long = (size) => size[0] / size[2];
  const oriented = item.category === 'furniture';
  if (target && oriented && item.yaw === undefined && (long(turned.size) > 1.3) !== (long(target.size) > 1.3) && Math.abs(Math.log(long(turned.size))) > 0.26) {
    yaw += Math.PI / 2;
    wrapper.setRotation(quarter(yaw));
    turned = boxOf(document);
  }
  // Furniture keeps the old footprint (placements and spacing were made for it); plants and rocks keep its height.
  const byHeight = item.category !== 'furniture';
  const scale = !target
    ? item.fit.height ? item.fit.height / turned.size[1] : item.fit.width / Math.max(turned.size[0], turned.size[2])
    : byHeight
      ? // Plants and rocks keep the height, but a much wider generated shape may not spread past its neighbours.
        Math.min(target.size[1] / turned.size[1], FOOTPRINT_SLACK * Math.min(target.size[0] / turned.size[0], target.size[2] / turned.size[2]))
      : Math.min(...[0, 1, 2].map((axis) => target.size[axis] / turned.size[axis]));
  const centre = (box, axis) => (box.min[axis] + box.max[axis]) / 2;
  // A replacement sits where the package model sat; catalog furniture stands on the origin.
  const goal = replace && target ? target : { min: [0, 0, 0], max: [0, 0, 0] };
  wrapper.setScale([scale, scale, scale]);
  wrapper.setTranslation([
    centre(goal, 0) - centre(turned, 0) * scale,
    goal.min[1] - turned.min[1] * scale,
    centre(goal, 2) - centre(turned, 2) * scale,
  ]);
  for (const material of document.getRoot().listMaterials()) {
    material.setMetallicFactor(0).setMetallicRoughnessTexture(null).setRoughnessFactor(ROUGHNESS);
  }
  await document.transform(dedup(), prune(), textureCompress({ encoder: sharp, targetFormat: 'webp', ...MAPS }));
  const output = join(outputDir, replace ? item.file : `decor/${item.id}.glb`);
  mkdirSync(dirname(output), { recursive: true });
  await io.write(output, document);
  if (!replace) await writePicture(image, join(outputDir, 'decor/thumbs', `${item.id}.webp`));
  const fitted = boxOf(document);
  const metres = (size) => size.map((value) => value.toFixed(2)).join(' x ');
  const was = target ? `was ${metres(target.size)}` : `fit ${JSON.stringify(item.fit)}`;
  return `${item.id}: ${metres(fitted.size)} m (${was}), yaw ${Math.round((yaw * 180) / Math.PI)}°`;
}

const unknown = [...wanted].filter((id) => !manifest.items.some((item) => item.id === id));
if (unknown.length) throw new Error(`not in scripts/props/manifest.json: ${unknown.join(', ')}`);
for (const item of manifest.items) {
  if (wanted.size && !wanted.has(item.id)) continue;
  console.log(await fit(item));
}
